type DatastreamStreamConfig struct {
	// Backfill strategy to automatically backfill the Stream's objects. Specific objects can be excluded.
	BackfillAll any
	// Backfill strategy to disable automatic backfill for the Stream's objects.
	BackfillNone any
	// Output only. The creation time of the stream.
	CreateTime any
	// Immutable. A reference to a KMS encryption key. If provided, it will be used to encrypt the data. If left blank, data will be encrypted using an internal Stream-specific encryption key provisioned through KMS.
	CustomerManagedEncryptionKey any
	// The configuration of the stream destination.
	DestinationConfig any
	// Required. Display name.
	DisplayName any
	// Output only. Errors on the Stream.
	Errors any
	// Labels.
	Labels any
	// Output only. If the stream was recovered, the time of the last recovery. Note: This field is currently experimental.
	LastRecoveryTime any
	// Output only. Identifier. The stream's name.
	Name any
	// Optional. Rule sets to apply to the stream.
	RuleSets any
	// Output only. Reserved for future use.
	SatisfiesPzi any
	// Output only. Reserved for future use.
	SatisfiesPzs any
	// The configuration of the stream source.
	SourceConfig any
	// The state of the stream.
	State any
	// Output only. The last update time of the stream.
	UpdateTime any
}

